#include <iostream>
#include <vector>
#include <algorithm>
#include <cstddef>

int main() {
    std::vector<int> original;
    int cantidad_entrada{0};
    std::cin >> cantidad_entrada;
    for (int entrada{0}; entrada < cantidad_entrada; ++entrada) {
        int dato{0};
        std::cin >> dato;
        original.push_back(dato);
    }
    auto ordenados = original;
    std::sort(ordenados.begin(), ordenados.end());
    std::cout << "Original:";
    for (int valor : original) { std::cout << valor << ";"; }
    std::cout << "\nOrdenados:";
    for (int valor : ordenados) { std::cout << valor << ";"; }
    int distintos = 0;
    for (std::size_t i = 0; i < ordenados.size(); ++i) {
        if (i == 0 || ordenados[i] != ordenados[i - 1]) { ++distintos; }
    }
    std::cout << "\nDistintos:" << distintos;
    return 0;
}

