#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cstddef>

int main() {
    std::vector<std::string> original{"b2", "a1", "b2"};
    auto ordenados = original;
    std::sort(ordenados.begin(), ordenados.end());

    std::cout << "Original:";
    for (const auto& etiqueta : original) {
        std::cout << etiqueta << ";";
    }
    std::cout << "\nOrdenados:";
    for (const auto& etiqueta : ordenados) {
        std::cout << etiqueta << ";";
    }

    int distintos{0};
    for (std::size_t i = 0; i < ordenados.size(); ++i) {
        if (i == 0 || ordenados[i] != ordenados[i - 1]) {
            ++distintos;
        }
    }
    std::cout << "\nDistintos:" << distintos;
    return 0;
}
